cd /tmp/<path> && python3 - <<'EOF'
from duration import parse_duration as p

bad = [
 "", "   ", "-", "--1h", "+1h", ".5h", "5.h", "0.3s", "30m1h", "1h1h",
 "1 h", "1h  30m", "1h\t30m", "5", "1.5", "00", "-0", "1:60", "1:5",
 "1:000", "1:00:60", "1.5:30", "1:30.5", "1h-30m", "1H", "1h30",
 "1.2.3h", "abc", "1h,30m", "1w1w", "1s1m", "1:2:3", "- 1h", "1h -30m",
 "1h 30", "0 0", "0.0", "0.0s0", "1:00:", ":", "1::30",
]
for s in bad:
    try:
        p(s)
    except ValueError:
        pass
    else:
        raise AssertionError("accepted invalid %r -> %r" % (s,p(s)))
print("invalid ok", len(bad))

for v in [None, 5, 1.5, b"1h", ["1h"], True]:
    try:
        p(v)
    except TypeError:
        pass
    else:
        raise AssertionError("no TypeError for %r" % (v,))
print("type ok")

# whitespace allowed on both ends
assert p("\t 1h 30m \n") == 5400
print("strip ok")
EOF

